    private static function isGreeting(string $q): bool
    {
        if (mb_strlen($q, 'UTF-8') > 30) {
            return false;
        }
        return self::containsAny($q, self::GREETING_WORDS) && self::matchExtraArea($q) === null
            && !self::containsAny($q, self::REMEDY_WORDS);
    }

    private static function areaPhrases(): array
    {
        static $phrases = null;
        if ($phrases !== null) {
            return $phrases;
        }
        $phrases = self::EXTRA_PHRASES;
        $kb = json_decode((string) file_get_contents(self::kbFile('/knowledge/ai-astrologer/rules/life-areas.json')), true) ?: [];
        foreach (($kb['areas'] ?? []) as $area) {
            $id = (string) ($area['id'] ?? '');
            foreach (($area['customerPhrases'] ?? []) as $list) {
                foreach ((array) $list as $p) {
                    $phrases[$id][] = (string) $p;
                }
            }
        }
        foreach ($phrases as $id => $list) {
            $phrases[$id] = array_values(array_unique($list));
        }
        return $phrases;
    }

    private static function matchExtraArea(string $q): ?string
    {
        $best = null;
        $bestScore = 0;
        $generic = 0;
        foreach (self::areaPhrases() as $areaId => $words) {
            $score = 0;
            foreach ($words as $w) {
                if (self::hasWord($q, $w)) {
                    $score += mb_strlen($w, 'UTF-8');
                }
            }
            // current-guidance is the generic fallback; any specific area wins over it.
            if ($areaId === 'current-guidance') {
                $generic = $score;
                continue;
            }
            if ($score > $bestScore) {
                $best = $areaId;
                $bestScore = $score;
            }
        }
        // A question about the period itself ("what is my current dasha")
        // stays with current-guidance even if it also names an area word;
        // a soft word like "this year" does not outrank a specific area.
        if ($best === null) {
            return $generic > 0 ? 'current-guidance' : null;
        }
        return self::containsAny($q, self::PERIOD_WORDS) ? 'current-guidance' : $best;
    }

    private static function mentionedPlanet(string $q): ?string
    {
        foreach (self::PLANET_NAMES as $graha => $names) {
            foreach ($names as $n) {
                if (self::hasWord($q, $n)) {
                    return $graha;
                }
            }
        }
        return null;
    }

    /**
     * Caps the bubbles at four, puts the source line on the last one, and runs
     * the same output guard on every local reply. A health word without a doctor
     * line gets the doctor line; anything else that fails ships the safe
     * fallback and offers the astrologer.
     */
    private static function finish(array $bubbles, string $sourceLine, ?string $areaId, bool $handoff, string $lang): array
    {
        $bubbles = array_values(array_filter(array_map('trim', $bubbles), static function ($b) {
            return $b !== '';
        }));
        if (count($bubbles) > 4) {
            $head = array_slice($bubbles, 0, 3);
            $head[] = implode("\n\n", array_slice($bubbles, 3));
            $bubbles = $head;
        }

        $check = AstroAiProvider::checkReply(implode("\n\n", $bubbles), $lang);
        if (!$check['ok'] && $check['violations'] === ['health topic without advising a qualified doctor']) {
            $bubbles[] = self::doctorLine($lang);
            $check = AstroAiProvider::checkReply(implode("\n\n", $bubbles), $lang);
        }
        if (!$check['ok']) {
            error_log('AI Astrologer (knowledge-base mode) guard rejected a reply: ' . implode('; ', $check['violations']));
            $fallback = AstroAiProvider::fallbackReply($lang);
            return ['content' => $fallback, 'bubbles' => [$fallback], 'sourceLine' => '',
                'areaId' => $areaId, 'handoff' => true, 'mode' => 'knowledge-base'];
        }

        if ($sourceLine !== '') {
            $bubbles[count($bubbles) - 1] .= "\n" . $sourceLine;
        }
        return [
            'content' => implode("\n\n", $bubbles),
            'bubbles' => $bubbles,
            'sourceLine' => $sourceLine,
            'areaId' => $areaId,
            'handoff' => $handoff,
            'mode' => 'knowledge-base',
        ];
    }
